package com.pathstudy.assessment.domain;
import com.pathstudy.curriculum.domain.AuditedEntity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDateTime;
@Entity @Table(name="attempt_answers",uniqueConstraints=@UniqueConstraint(name="uk_attempt_answer_attempt_item",columnNames={"assessment_attempt_id","assessment_item_id"}),indexes={@Index(name="idx_attempt_answer_attempt",columnList="assessment_attempt_id"),@Index(name="idx_attempt_answer_item",columnList="assessment_item_id")}) @Getter @Setter @NoArgsConstructor public class AttemptAnswer extends AuditedEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="assessment_attempt_id",nullable=false) private AssessmentAttempt assessmentAttempt; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="assessment_item_id",nullable=false) private AssessmentItem assessmentItem; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="selected_option_id") private QuestionOption selectedOption; @Column(length=4000) private String answerPayload; private Boolean isCorrect; @Column(precision=10,scale=2) private BigDecimal earnedScore; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private GradingStatus gradingStatus=GradingStatus.NOT_GRADED; private LocalDateTime answeredAt; private Integer timeSpentSeconds; @Column(length=4000) private String feedbackSnapshot; }
